import{_ as a,o as s,c as t,a6 as i}from"./chunks/framework.BBIckNDn.js";const m=JSON.parse('{"title":"第8部 演習 — ビルドとライブラリ","description":"","frontmatter":{"title":"第8部 演習 — ビルドとライブラリ","study":{"source":"C++ Wiki","kind":"演習","status":"既存原稿","summary":"次の道具はどの層のものですか(メタビルド/ビルドシステム/コンパイラ/リンカ/その他)。 Ninja 2. CMake 3. cl.exe 4. link.exe 5. clang-tidy 6. AddressSanitizer"}},"headers":[],"relativePath":"tools/build/exercises.md","filePath":"tools/build/exercises.md"}'),l={name:"tools/build/exercises.md"};function o(d,e,n,r,c,u){return s(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="第8部-演習-—-ビルドとライブラリ" tabindex="-1">第8部 演習 — ビルドとライブラリ <a class="header-anchor" href="#第8部-演習-—-ビルドとライブラリ" aria-label="Permalink to &quot;第8部 演習 — ビルドとライブラリ&quot;">​</a></h1><h2 id="問1-概念確認" tabindex="-1">問1. 概念確認 <a class="header-anchor" href="#問1-概念確認" aria-label="Permalink to &quot;問1. 概念確認&quot;">​</a></h2><p>次の道具はどの層のものですか(メタビルド/ビルドシステム/コンパイラ/リンカ/その他)。</p><ol><li>Ninja 2. CMake 3. cl.exe 4. link.exe 5. clang-tidy 6. AddressSanitizer</li></ol><details><summary>解答</summary><ol><li>ビルドシステム。2. メタビルド(設計図からNinja等を生成 — 自身はビルドしない)。3. コンパイラ(MSVC)。4. リンカ(MSVC)。5. 静的解析ツール(Clang基盤)。6. コンパイラが埋め込む実行時検査(サニタイザ)(<a href="/study/tools/build/what-is-build.html">ビルドとは</a>、<a href="/study/tools/build/debugging-and-analysis.html">品質ツール</a>)。</li></ol></details><h2 id="問2-コード読解-エラーメッセージ" tabindex="-1">問2. コード読解(エラーメッセージ) <a class="header-anchor" href="#問2-コード読解-エラーメッセージ" aria-label="Permalink to &quot;問2. コード読解(エラーメッセージ)&quot;">​</a></h2><p>次のエラーの原因として最も可能性が高いものと、確認手順を答えてください。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>error LNK2038: &#39;_ITERATOR_DEBUG_LEVEL&#39; の不一致が検出されました。</span></span>
<span class="line"><span>値 &#39;0&#39; が 2 の値 &#39;main.obj&#39; と一致しません。(physics.lib)</span></span></code></pre></div><details><summary>解答</summary><p>physics.lib が<strong>Release構成</strong>(IDL=0)でビルドされ、main.objが<strong>Debug構成</strong>(IDL=2)——構成違いのバイナリ混在(<a href="/study/tools/build/link-errors.html">ABI互換性</a>)。確認: physics.libの入手元がDebug/Release両方を提供しているか、自分のリンク設定がどちらの.libを指しているか。対処: 構成ごとに対応する.libをリンクする(CMakeなら <code>$&lt;CONFIG&gt;</code> で分岐)。</p></details><h2 id="問3-問題のある構成の改善" tabindex="-1">問3. 問題のある構成の改善 <a class="header-anchor" href="#問3-問題のある構成の改善" aria-label="Permalink to &quot;問3. 問題のある構成の改善&quot;">​</a></h2><p>「common.h に全クラスのincludeとよく使う定数を集約し、全.cppがこれをincludeしている。定数を1つ変えると全ビルド(15分)が走る」。改善案を3つ、効果順に挙げてください。</p><details><summary>解答の要点</summary><p>(1) <strong>common.hの解体</strong>: 定数系(高頻度変更)とライブラリinclude(低頻度)を分離し、各.cppは必要なものだけincludeする——変更の波及範囲を縮める根本対策(<a href="/study/tools/build/build-speed.html">ビルド時間</a>、<a href="/study/design/foundations/cohesion-and-coupling.html">凝集度</a>の物理版)。(2) 低頻度変更部分(標準ライブラリ等)を<strong>PCH化</strong>——パースの重複を除去。(3) 調整頻度の高い定数は<strong>データファイル化</strong>(ホットリロード)し、コンパイル自体を不要に(<a href="/study/game/patterns/type-object-and-sandbox.html">Type Object</a>方向)。</p></details><h2 id="問4-設計比較" tabindex="-1">問4. 設計比較 <a class="header-anchor" href="#問4-設計比較" aria-label="Permalink to &quot;問4. 設計比較&quot;">​</a></h2><p>社内ライブラリ「math_utils」を、(a) ヘッダーオンリー(全部inline/テンプレート)、(b) 静的ライブラリ、(c) DLL、のどれで配るか。利用チームが5つ、更新頻度は月1、性能クリティカルな小関数中心、という条件で比較してください。</p><details><summary>解答の要点</summary><p>(a) 小関数のインライン化が効く(性能◎)、導入が楽。代償: 利用側のビルド時間増、更新が全チームの再コンパイル。(b) ビルド時間は改善するが、小関数の呼び出しコスト(LTOで緩和可)とバージョン運用が必要。(c) 月1更新でDLL差し替えは魅力だが、C++ ABI境界の危険(コンパイラ・構成の統一が必要)と小関数のDLL呼び出しコストで不利(<a href="/study/runtime/cpp-internals/object-files-and-libraries.html">ライブラリ</a>)。この条件(小関数・性能重視)なら**(a)が定石**。数学ライブラリがヘッダーオンリー(glm等)なのはこの理由。</p></details><h2 id="問5-デバッグ問題" tabindex="-1">問5. デバッグ問題 <a class="header-anchor" href="#問5-デバッグ問題" aria-label="Permalink to &quot;問5. デバッグ問題&quot;">​</a></h2><p>「昨日まで通っていたビルドが、ライブラリを最新版に上げたら <code>undefined reference to Physics::Step(float)</code> になった」。考えられる原因を2つと確認方法を書いてください。</p><details><summary>解答の要点</summary><p>(1) 新版でシグネチャが変わった(<code>Step(float, int)</code> になった等): ヘッダーは新しいが.libが古い(またはその逆)——<code>nm/dumpbin</code> で.lib側の提供シンボルを確認し、ヘッダーの宣言と突き合わせる(<a href="/study/tools/build/link-errors.html">リンクエラー</a>)。(2) 新版でその関数がinline化/削除/別モジュール移動された: リリースノートとヘッダーdiffを確認。教訓: <strong>ライブラリ更新はヘッダーとバイナリをセットで</strong>+クリーンビルド。</p></details><h2 id="問6-説明問題" tabindex="-1">問6. 説明問題 <a class="header-anchor" href="#問6-説明問題" aria-label="Permalink to &quot;問6. 説明問題&quot;">​</a></h2><p>「なぜUnityではビルドのことをほぼ考えなくてよかったのに、C++では一大テーマなのか」を、ヘッダー・テンプレート・ABIの3語を使って4文以内で説明してください。</p><details><summary>解答例</summary><p>C#は通常ヘッダーではなくアセンブリのメタデータから型を参照するため、C++のテキストincludeと同じ宣言の再パースは不要です。ジェネリックはILとメタデータに表現され、機械語化やコード共有の方法は型とJIT/AOT方式に依存し、C++の翻訳単位ごとのテンプレート実体化とは異なります。マネージド参照にも対象API・アセンブリと依存の版・実行環境の互換条件があり、UnityのIL2CPPやネイティブプラグインにはC++側のビルドとABIの条件も加わります。C++ではヘッダー、テンプレート、ライブラリ境界のABIを管理する必要があり、実行時の表現や最適化を細かく制御できる一方、性能は実装と計測で確かめます(<a href="/study/tools/build/build-speed.html">ビルド時間</a>、<a href="/study/runtime/cpp-internals/symbols-and-linkage.html">ABI</a>)。</p></details><h2 id="問7-小規模実装問題" tabindex="-1">問7. 小規模実装問題 <a class="header-anchor" href="#問7-小規模実装問題" aria-label="Permalink to &quot;問7. 小規模実装問題&quot;">​</a></h2><p><a href="/study/tools/build/samples/cmake-demo.html">samples/cmake_demo/</a> を拡張してください:</p><ol><li>新ライブラリ <code>game_ai</code>(game_coreに依存)をターゲットとして追加</li><li>Debug構成でのみ <code>GAME_DEBUG_DRAW</code> をdefine(<code>target_compile_definitions</code> + <code>$&lt;CONFIG:Debug&gt;</code>)</li><li>(発展)<code>enable_testing()</code> + 最小のテスト実行ターゲット</li></ol><details><summary>評価基準</summary><p>(a) 依存の向きが game_ai → game_core の一方向で、逆リンクがない(<a href="/study/design/foundations/dependency.html">依存の方向</a>のビルドでの表現)。(2) Release構成でdefineが消えることを確認。(3) <code>ctest</code> が走れば完了。</p></details><hr><p>前: <a href="/study/tools/build/link-errors.html">リンクエラー</a> | <a href="/study/tools/build/">カテゴリ目次</a> | <a href="/study/languages/csharp/">第9部: Unity/C#との対応へ</a></p>`,27)])])}const p=a(l,[["render",o]]);export{m as __pageData,p as default};
